/**
 * Email address identity, shared by every path that stores or looks up an
 * account (ADR 0003 §3–4).
 *
 * Addresses are case-insensitive: one canonical spelling is stored, and every
 * lookup compares in that spelling, so `Alice@Example.com` and
 * `alice@example.com` are the same account however they were typed. The Zod
 * `emailSchema` lowercases what the forms submit, but the services and
 * repositories must not rely on having been reached through a form.
 */

/** The canonical (stored and compared) spelling of an address. */
export function normalizeEmail(email: string): string {
  return email.toLowerCase();
}

/** Sign-up was attempted with an address that already has an account. */
export class EmailTakenError extends Error {
  readonly code = "conflict" as const;

  constructor(message = "An account with that email already exists.") {
    super(message);
    this.name = "EmailTakenError";
  }
}
EOF
