const SUFFIX_ROOM = 5;

/**
 * The longest prefix shared by every slug `uniqueSlug()` can derive from
 * `base`, however long the numeric suffix grows (up to 15 digits). A
 * repository that pre-filters the `taken` set has to scan on this prefix —
 * not on the full base — or the suffixed variants of a maximum-length slug
 * are missed.
 */
export function slugFamilyPrefix(base: string): string {
  return base.slice(0, SLUG_MAX_LENGTH - 16).replace(/-+$/g, "");
}

/**
 * Derives a slug from `input` that collides with nothing in `taken`, by
