 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other. The rules are ADR
 * 0003's:
 *
 * - throttled on the anonymous `auth:register` bucket, charged once per
 *   attempt and before anything is read or written;
 * - an address that already has an account, in any spelling, is refused as a
 *   `conflict` and nothing is created;
 * - everything that could refuse the sign-up (the name and slug derivation,
 *   the password hash) is settled before the first write, and the writes then
 *   run user → workspace → owner membership, publishing `member.joined` once
 *   (inside `createOrganization`);
 * - the workspace starts on the Free plan with an active subscription;
 * - one welcome email goes to the stored address, naming the workspace.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitedError(REGISTER_BUCKET, verdict.resetAt);
  }

  const email = normalizeEmail(input.email);
  if (await userRepo.findUserByEmail(email)) {
    throw new EmailTakenError();
  }

  const passwordHash = await hashPassword(input.password);
  const workspaceName = firstWorkspaceName(input.name);
  const workspaceSlug = await deriveFirstWorkspaceSlug(input.name);

  const user = await userRepo.insertUser({
    email,
    name: input.name,
    passwordHash,
  });

  // The slug handed over is already valid, unreserved and free;
  // `createOrganization` re-checks it and re-suffixes it should another
  // sign-up have claimed it in the meantime.
  const org = await createOrganization(user.id, {
    name: workspaceName,
    slug: workspaceSlug,
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

